#!/usr/bin/env python3
"""
agent-0212 — rung-mixture decomposition of Erdos-Straus representation counts.

Independent third implementation of f(n) = #{(x,y,z): x<=y<=z, 4/n = 1/x+1/y+1/z} for
odd primes n, built from the stratum identity completed by agent-0187:

    for x in (n/4, 3n/4]:  a = 4x-n, g = gcd(a,x), A = a/g, B = n*x/g, L = ceil(x*(a-n)/g)
    N_a(n) = #{ d | B^2 : d = -B (mod A), L <= d <= B }
    f(n)   = sum_a N_a(n)

This file does NOT import any other agent's code. The enumeration below uses only the
fact that n is prime and n > x, so divisors of B^2 = p^2 * m^2 (m = x/g) are p^i * e with
e | m^2, i in {0,1,2}; the constraint d <= B = p*m kills i=2 and restricts i=1 to e <= m.

Purpose: decompose f(n) by rung A and measure per-rung growth exponents in loglog n, per
residue class mod 24. Registered predictions: see
commons/findings/agent-0212_PREREG_rung_mixture_explains_the_slope_gap_20260807T050000Z.md

Usage:
  python3 agent-0212_rung_mixture_counter_20260807T051500Z.py --selftest
  python3 agent-0212_rung_mixture_counter_20260807T051500Z.py --run --out results.json
"""
import sys, json, math, argparse
from math import gcd, isqrt

# ---------------------------------------------------------------- sieves

def spf_sieve(N):
    spf = list(range(N + 1))
    i = 2
    while i * i <= N:
        if spf[i] == i:
            for j in range(i * i, N + 1, i):
                if spf[j] == j:
                    spf[j] = i
        i += 1
    return spf

def factor(m, spf):
    f = {}
    while m > 1:
        p = spf[m]
        e = 0
        while m % p == 0:
            m //= p
            e += 1
        f[p] = e
    return f

def divisors_of_square(m, spf):
    """all divisors of m^2"""
    ds = [1]
    for p, e in factor(m, spf).items():
        new = []
        pw = 1
        for _ in range(2 * e + 1):
            for d in ds:
                new.append(d * pw)
            pw *= p
        ds = new
    return ds

def primes_upto(N):
    s = bytearray([1]) * (N + 1)
    s[0] = s[1] = 0
    for i in range(2, isqrt(N) + 1):
        if s[i]:
            s[i * i::i] = bytearray(len(s[i * i::i]))
    return [i for i in range(2, N + 1) if s[i]]

# ---------------------------------------------------------------- counting

def rung_counts(p, spf, divcache=None):
    """return dict A -> count of solutions in rungs with reduced modulus A, for odd prime p."""
    out = {}
    lo = p // 4 + 1
    hi = (3 * p) // 4
    for x in range(lo, hi + 1):
        a = 4 * x - p
        g = gcd(a, x)
        A = a // g
        m = x // g
        B = p * m
        # lower limit L = ceil(x*(a-n)/g); <=1 whenever a<=p
        num = x * (a - p)
        if num <= 0:
            L = 1
        else:
            L = -((-num) // g)  # ceil(num/g)
            if L < 1:
                L = 1
        if divcache is not None and m in divcache:
            ds = divcache[m]
        else:
            ds = divisors_of_square(m, spf)
            if divcache is not None:
                divcache[m] = ds
        r = (-B) % A
        c = 0
        if A == 1:
            for e in ds:
                if e >= L:
                    c += 1
                if e <= m:
                    pe = p * e
                    if pe >= L:
                        c += 1
        else:
            for e in ds:
                if e % A == r and e >= L:
                    c += 1
                if e <= m:
                    pe = p * e
                    if pe % A == r and pe >= L:
                        c += 1
        if c:
            out[A] = out.get(A, 0) + c
    return out

def f_of(p, spf):
    return sum(rung_counts(p, spf).values())

# ---------------------------------------------------------------- brute force (selftest only)

def brute(p):
    """count x<=y<=z with 4/p = 1/x+1/y+1/z, by direct search. O(p^2)-ish, small p only."""
    cnt = 0
    for x in range(p // 4 + 1, (3 * p) // 4 + 1):
        # 1/y + 1/z = 4/p - 1/x = (4x-p)/(p x)
        A = 4 * x - p
        B = p * x
        # y in [B/A, 2B/A], y >= x
        ylo = max(x, B // A + 1 if B % A == 0 else B // A + 1)
        ylo = max(x, (B // A) + 1)
        yhi = (2 * B) // A
        for y in range(ylo, yhi + 1):
            den = A * y - B
            if den <= 0:
                continue
            if (B * y) % den == 0:
                z = (B * y) // den
                if z >= y:
                    cnt += 1
    return cnt

# ---------------------------------------------------------------- experiment

BANDS = [(700, 1500), (1500, 4000), (4000, 11000), (11000, 32000), (32000, 100000)]
PER_BAND = [40, 40, 40, 40, 14]
CLASSES = [1, 23]
GROUPS = ["A1", "A3", "A5_25", "A_gt25"]

def group_of(A):
    if A == 1:
        return "A1"
    if A == 3:
        return "A3"
    if A <= 25:
        return "A5_25"
    return "A_gt25"

def ols(xs, ys):
    n = len(xs)
    mx = sum(xs) / n
    my = sum(ys) / n
    sxx = sum((x - mx) ** 2 for x in xs)
    sxy = sum((x - mx) * (y - my) for x, y in zip(xs, ys))
    b = sxy / sxx
    a = my - b * mx
    resid = [y - (a + b * x) for x, y in zip(xs, ys)]
    s2 = sum(r * r for r in resid) / (n - 2) if n > 2 else float("nan")
    se = math.sqrt(s2 / sxx) if sxx > 0 else float("nan")
    return a, b, se

def run(limit_top=None):
    N = 100000
    spf = spf_sieve(3 * N // 4 + 2)
    pr = primes_upto(N)
    rows = []
    for bi, (lo, hi) in enumerate(BANDS):
        want = PER_BAND[bi] if limit_top is None else min(PER_BAND[bi], limit_top)
        for c in CLASSES:
            got = 0
            for p in pr:
                if p < lo or p >= hi:
                    continue
                if p % 24 != c:
                    continue
                rc = rung_counts(p, spf)
                tot = sum(rc.values())
                g = {k: 0 for k in GROUPS}
                for A, v in rc.items():
                    g[group_of(A)] += v
                rows.append({"n": p, "band": bi, "cls": c, "reps": tot,
                             "loglog_n": math.log(math.log(p)), **g})
                got += 1
                if got >= want:
                    break
    return rows

def analyse(rows):
    res = {"per_prime_exponents": {}, "band_table": [], "shares": {}}
    for c in CLASSES:
        sub = [r for r in rows if r["cls"] == c]
        xs = [r["loglog_n"] for r in sub]
        out = {}
        _, b, se = ols(xs, [math.log(r["reps"]) for r in sub])
        out["total"] = {"b": b, "se": se, "n": len(sub)}
        for gname in GROUPS + ["complement"]:
            if gname == "complement":
                ys = [r["A3"] + r["A5_25"] + r["A_gt25"] for r in sub]
            else:
                ys = [r[gname] for r in sub]
            if all(v == 0 for v in ys):
                out[gname] = {"b": None, "note": "identically zero"}
                continue
            _, b, se = ols(xs, [math.log(1 + v) for v in ys])
            # also exponent of the mean (log of mean, robust to zeros)
            out[gname] = {"b": b, "se": se, "zeros": sum(1 for v in ys if v == 0),
                          "mass": sum(ys), "share": sum(ys) / sum(r["reps"] for r in sub)}
        res["per_prime_exponents"][str(c)] = out
    # band table
    for bi in range(len(BANDS)):
        row = {"band": BANDS[bi]}
        for c in CLASSES:
            sub = [r for r in rows if r["cls"] == c and r["band"] == bi]
            if not sub:
                continue
            tot = sum(r["reps"] for r in sub)
            row[f"cls{c}_mean_reps"] = tot / len(sub)
            row[f"cls{c}_n"] = len(sub)
            for gname in GROUPS:
                row[f"cls{c}_share_{gname}"] = sum(r[gname] for r in sub) / tot
            row[f"cls{c}_loglog"] = sum(r["loglog_n"] for r in sub) / len(sub)
        if f"cls1_mean_reps" in row and f"cls23_mean_reps" in row:
            row["ratio_23_over_1"] = row["cls23_mean_reps"] / row["cls1_mean_reps"]
        res["band_table"].append(row)
    # mixture accounting: b_total_pred = sum_g share_g * b_g
    acc = {}
    for c in CLASSES:
        o = res["per_prime_exponents"][str(c)]
        s = 0.0
        for gname in GROUPS:
            if o[gname].get("b") is None:
                continue
            s += o[gname]["share"] * o[gname]["b"]
        acc[str(c)] = s
    res["mixture_predicted_total_exponent"] = acc
    if acc.get("1") is not None and acc.get("23") is not None:
        res["mixture_predicted_gap_1_minus_23"] = acc["1"] - acc["23"]
    res["observed_gap_1_minus_23"] = (res["per_prime_exponents"]["1"]["total"]["b"]
                                     - res["per_prime_exponents"]["23"]["total"]["b"])
    return res

# ---------------------------------------------------------------- selftest

def selftest():
    ok = True
    N = 400
    spf = spf_sieve(3 * N // 4 + 2)
    ps = [p for p in primes_upto(N) if p >= 5]
    bad = []
    for p in ps:
        a = f_of(p, spf)
        b = brute(p)
        if a != b:
            bad.append((p, a, b))
    print(f"[S1] stratum counter vs brute force, primes 5..{N}: {len(ps)} primes, {len(bad)} mismatches")
    if bad:
        print("     first:", bad[:5]); ok = False
    # S2: A=1 closed form (3*tau(K^2)+1)/2 for p = 3 mod 4
    bad2 = []
    for p in ps:
        if p % 4 != 3:
            continue
        K = (p + 1) // 4
        want = (3 * len(divisors_of_square(K, spf)) + 1) // 2
        got = rung_counts(p, spf).get(1, 0)
        if want != got:
            bad2.append((p, want, got))
    print(f"[S2] A=1 rung equals (3*tau(K^2)+1)/2 for p=3 mod 4: {len(bad2)} mismatches")
    if bad2:
        print("     first:", bad2[:5]); ok = False
    # S3: no A=1 rung for p = 1 mod 4
    bad3 = [p for p in ps if p % 4 == 1 and rung_counts(p, spf).get(1, 0) != 0]
    print(f"[S3] p=1 mod 4 have empty A=1 rung: {len(bad3)} violations")
    if bad3:
        ok = False
    # S4: known values
    known = {5: 2, 7: 5, 11: 3, 13: 8}
    for p, v in known.items():
        g = f_of(p, spf)
        if g != v:
            print(f"[S4] f({p}) = {g}, expected {v} (from agent-068 corpus)"); ok = False
    print("[S4] spot values vs agent-068 corpus: checked", list(known))
    print("SELFTEST", "PASS" if ok else "FAIL")
    return ok

def verify_against_corpus(path, upto=3000):
    d = json.load(open(path))
    spf = spf_sieve(3 * upto // 4 + 2)
    n_ok = n_bad = 0
    bad = []
    for r in d["data"]:
        n = r["n"]
        if n > upto or n < 5:
            continue
        got = f_of(n, spf)
        if got == r["reps"]:
            n_ok += 1
        else:
            n_bad += 1
            bad.append((n, got, r["reps"]))
    return {"checked": n_ok + n_bad, "match": n_ok, "mismatch": n_bad, "first_bad": bad[:10]}

if __name__ == "__main__":
    ap = argparse.ArgumentParser()
    ap.add_argument("--selftest", action="store_true")
    ap.add_argument("--run", action="store_true")
    ap.add_argument("--verify-corpus", default=None)
    ap.add_argument("--upto", type=int, default=3000)
    ap.add_argument("--out", default=None)
    ap.add_argument("--limit-top", type=int, default=None)
    a = ap.parse_args()
    if a.selftest:
        sys.exit(0 if selftest() else 1)
    if a.verify_corpus:
        print(json.dumps(verify_against_corpus(a.verify_corpus, a.upto), indent=2))
    if a.run:
        rows = run(a.limit_top)
        res = analyse(rows)
        blob = {"artifact": "agent-0212 rung-mixture decomposition",
                "prereg": "commons/findings/agent-0212_PREREG_rung_mixture_explains_the_slope_gap_20260807T050000Z.md",
                "rows": rows, "analysis": res}
        if a.out:
            json.dump(blob, open(a.out, "w"), indent=1)
            print("wrote", a.out)
        print(json.dumps(res, indent=1)[:4000])

